/// The Turek-Hron rule table for `u_bar`: walls and body `Wall` /
/// `ZeroGradient`, inlet `Inlet`/`ZeroGradient`, outlet
/// `ZeroGradient`/`Fixed(0)` (the paper's do-nothing), the empties
/// `Empty`/`Empty`.
pub fn turek_rules(u_bar: Scalar) -> Vec<(&'static str, VelocityBc, PressureBc)> {
    vec![
        ("empty_back", VelocityBc::Empty, PressureBc::Empty),
        ("empty_front", VelocityBc::Empty, PressureBc::Empty),
        ("wall_top", VelocityBc::Wall, PressureBc::ZeroGradient),
        (
            "cylinder",
            VelocityBc::Wall,
            PressureBc::ZeroGradient,
        ),
        ("wall_bottom", VelocityBc::Wall, PressureBc::ZeroGradient),
        (
            "inlet",
            VelocityBc::Inlet { u_bar },
            PressureBc::ZeroGradient,
        ),
        ("outlet", VelocityBc::ZeroGradient, PressureBc::Fixed(0.0)),
        (
            "fluid_to_flap",
            VelocityBc::Wall,
            PressureBc::ZeroGradient,
        ),
    ]
}

/// Steady SIMPLE: `alpha_U` 0.7, `alpha_p` 0.3 (SPEC-LIT 5.2's pairing).
pub fn steady_controls() -> SimpleControls {
    SimpleControls {
        momentum: MomentumControls {
            nu: NU,
            u_solver: SolverControls {
                solver: LinearSolverKind::PBiCGStab,
                tolerance: 1e-10,
                rel_tol: 0.1,
                max_iter: 200,
                precon: Preconditioner::Dilu,
                check_interval: 5,
                ..SolverControls::default()
            },
            u_relax: 0.7,
            div_scheme: DivScheme::LinearUpwind,
            bounded_convection: true,
            sn_grad: crate::fv::SnGradScheme::Corrected,
            variable_viscosity_stress: false,
            ..MomentumControls::default()
        },
        p_solver: SolverControls {
            solver: LinearSolverKind::PCG,
            tolerance: 1e-10,
            rel_tol: 0.05,
            max_iter: 2000,
            precon: Preconditioner::Dic,
            check_interval: 5,
            ..SolverControls::default()
        },
        p_relax: 0.3,
        n_non_orth_correctors: 1,
        n_correctors: 1,
        n_outer_correctors: 1,
        momentum_predictor: true,
        report_continuity: true,
    }
}

fn write_system(case_dir: &Path) -> Result<()> {
    let dir = case_dir.join("system");

    write_dict(
        &dir,
        "controlDict",
        "application     foamRun;
\
         startFrom       startTime;
\
         startTime       0;
\
         stopAt          endTime;
\
         endTime         1;
\
         deltaT          1;
\
         writeControl    timeStep;
\
         writeInterval   1;
\
         purgeWrite      0;
\
         writeFormat     ascii;
\
         writePrecision  6;
\
         writeCompression off;
\
         timeFormat      general;
\
         timePrecision   6;
\
         runTimeModifiable true;",
    )?;

    write_dict(
        &dir,
        "fvSchemes",
        "ddtSchemes
{
    default         steadyState;
}

\
         gradSchemes
{
    default         Gauss linear;
}

\
         divSchemes
{
    default         none;
\
         \x20   div(phi,U)       Gauss linearUpwind grad(U);
\
         \x20   div(phi,T)       bounded Gauss upwind;
\
         \x20   div(phi,k)       bounded Gauss upwind;
\
         \x20   div(phi,epsilon) bounded Gauss upwind;
\
         \x20   div(phi,omega)   bounded Gauss upwind;
\
         \x20   div(phi,nuTilda) bounded Gauss upwind;
}

\
         laplacianSchemes
{
    default         Gauss linear corrected;
}

\
         interpolationSchemes
{
    default         linear;
}

\
         snGradSchemes
{
    default         corrected;
}",
    )?;

    // ofgpu looks up solvers/<var>/... by exact name, so the sub-dictionaries
    // are written out one per variable rather than behind a regex key.
    //
    // `p` and `U` are here for `ofgpu-buoyant`; the frozen-flow drivers never
    // look them up. `p` is the one entry whose settings actually matter: the
    // pressure Poisson equation is diagonally weak and takes hundreds of
    // sweeps where every other equation here takes three, so it gets DIC
    // rather than Jacobi and a budget to match. `relTol 0.01` is deliberate
    // too - inside a SIMPLE loop the pressure only has to be solved as well as
    // the coefficients it was assembled from deserve, and driving it to 1e-8
    // on an outer iteration that is about to change `rAUf` is wasted work.
    write_dict(
        &dir,
        "fvSolution",
        "solvers
{
\
         \x20   p
    {
\
         \x20       solver          PBiCGStab;
\
         \x20       preconditioner  DIC;
\
         \x20       tolerance       1e-08;
\
         \x20       relTol          0.01;
\
         \x20       maxIter         1000;
\
         \x20   }

\
         \x20   Phi
    {
\
         \x20       solver          PBiCGStab;
\
         \x20       preconditioner  DIC;
\
         \x20       tolerance       1e-12;
\
         \x20       relTol          0;
\
         \x20       maxIter         5000;
\
         \x20   }

\
         \x20   U
    {
\
         \x20       solver          PBiCGStab;
\
         \x20       preconditioner  diagonal;
\
         \x20       tolerance       1e-08;
\
         \x20       relTol          0.1;
\
         \x20       maxIter         200;
\
         \x20   }

\
         \x20   T
    {
\
         \x20       solver          PBiCGStab;
\
         \x20       preconditioner  diagonal;
\
         \x20       tolerance       1e-08;
\
         \x20       relTol          0.01;
\
         \x20       maxIter         200;
\
         \x20   }

\
         \x20   k
    {
\
         \x20       solver          PBiCGStab;
\
         \x20       preconditioner  diagonal;
\
         \x20       tolerance       1e-08;
\
         \x20       relTol          0.01;
\
         \x20       maxIter         200;
\
         \x20   }

\
         \x20   epsilon
    {
\
         \x20       solver          PBiCGStab;
\
         \x20       preconditioner  diagonal;
\
         \x20       tolerance       1e-08;
\
         \x20       relTol          0.01;
\
         \x20       maxIter         200;
\
         \x20   }

\
         \x20   omega
    {
\
         \x20       solver          PBiCGStab;
\
         \x20       preconditioner  diagonal;
\
         \x20       tolerance       1e-08;
\
         \x20       relTol          0.01;
\
         \x20       maxIter         200;
\
         \x20   }

\
         \x20   nuTilda
    {
\
         \x20       solver          PBiCGStab;
\
         \x20       preconditioner  diagonal;
\
         \x20       tolerance       1e-08;
\
         \x20       relTol          0.01;
\
         \x20       maxIter         200;
\
         \x20   }
}

\
         SIMPLE
{
    nNonOrthogonalCorrectors 0;
}

\
         // U 0.7 with p 0.3 is what OpenFOAM's buoyant cases use, and the two
\
         // summing to one is the usual rule of thumb behind it.
\
         relaxationFactors
{
    fields
    {
\
         \x20       p               0.3;
\
         \x20   }

\
         \x20   equations
    {
\
         \x20       U               0.7;
\
         \x20       T               0.7;
\
         \x20       k               0.7;
\
         \x20       epsilon         0.7;
\
         \x20       omega           0.7;
\
         \x20       nuTilda         0.7;
\
         \x20   }
}",
    )
}
